121	    std::map<Bdf, int64_t>   by_bdf;
122	    std::map<int64_t, void*> handles;
123	    for (int64_t i : devices) {
124	        Bdf bdf{};
125	        if (!device_bdf(i, bdf)) {
126	            return std::nullopt;
127	        }
128	        by_bdf[bdf] = i;
129	        char bus_id[32];
130	        std::snprintf(bus_id, sizeof(bus_id), "%08x:%02x:%02x.0", bdf.domain, bdf.bus, bdf.device);
131	        void* h = nullptr;
132	        if (lib.handle_by_pci_bus_id(bus_id, &h) != kNvmlSuccess) {
133	            return std::nullopt;
134	        }
135	        handles[i] = h;
136	    }
137	
138	    std::map<std::pair<int64_t, int64_t>, bool> linked;
139	    for (int64_t i : devices) {
140	        for (int64_t j : devices) {
141	            linked[{i, j}] = (i == j);
142	        }
143	    }
144	
145	    std::set<int64_t> on_switch;
146	    for (const auto& entry : handles) {
147	        // Per DEVICE, not once for the whole sweep. Shared, the first device to answer would let
148	        // every later one that NVML refused keep the `false` it was initialised with above -- and
149	        // check_nvlink would then refuse the group claiming a link is missing, when the truth is
150	        // that nobody asked successfully. The header promises the opposite.
151	        bool answered = false;
152	        for (int link = 0; link < kMaxLinks; ++link) {
153	            unsigned       active = 0;
154	            const unsigned rc     = lib.nvlink_state(entry.second, static_cast<unsigned>(link), &active);
155	            if (rc == kNvmlNotSupported || rc == kNvmlInvalidArgument) {
156	                answered = true;  // the device has no more links, which is an answer
157	                break;
158	            }
159	            if (rc != kNvmlSuccess) {
160	                break;  // anything else means we genuinely could not ask
161	            }
162	            answered = true;
163	            if (active == 0) {
164	                continue;
165	            }
166	            unsigned kind = 0;
167	            if (lib.nvlink_remote_type(entry.second, static_cast<unsigned>(link), &kind) != kNvmlSuccess) {
168	                continue;
169	            }
170	            if (kind == kRemoteSwitch) {
171	                on_switch.insert(entry.first);
172	            }
173	            else if (kind == kRemoteGpu) {
174	                NvmlPciInfo info{};
175	                if (lib.nvlink_remote_pci(entry.second, static_cast<unsigned>(link), &info) != kNvmlSuccess) {
176	                    continue;
177	                }
178	                auto it = by_bdf.find(Bdf{info.domain, info.bus, info.device});
179	                if (it != by_bdf.end()) {
180	                    linked[{entry.first, it->second}] = true;
181	                    linked[{it->second, entry.first}] = true;
182	                }
183	            }
184	        }
185	        // One device we could not probe makes the whole matrix unusable: its row and column would
186	        // read as "not linked" and be indistinguishable from a real absence of links.
187	        if (!answered) {
188	            return std::nullopt;
189	        }
190	    }
191	
192	    // One fabric per node, so every GPU with a switch link can reach every other one.
193	    for (int64_t i : on_switch) {
194	        for (int64_t j : on_switch) {
195	            linked[{i, j}] = true;
196	        }
197	    }
198	    return linked;
199	}
