201	std::string check_nvlink(const std::vector<int64_t>& devices)
202	{
203	    const auto matrix = nvlink_matrix(devices);
204	    if (!matrix.has_value()) {
205	        return {};
206	    }
207	    for (int64_t i : devices) {
208	        for (int64_t j : devices) {
209	            if (i != j && !matrix->at({i, j})) {
210	                return "cuda:" + std::to_string(i) + " and cuda:" + std::to_string(j)
211	                       + " are not joined by NVLink. fast-ulysses writes peer memory directly, which over "
212	                         "PCIe -- and especially across a CPU socket -- is slower than torch.distributed, "
213	                         "because that routes around the link instead. Use torch.distributed for this "
214	                         "group, or pass require_nvlink=False to measure it anyway. `fast-ulysses doctor` "
215	                         "prints the full matrix.";
216	            }
217	        }
218	    }
219	    return {};
220	}
